export interface CoverPdfInput {
  title: string;
  author: string;
  backText: string;
  printPages: number;
  spine: number;
  frontImage: string;
  frontWidth: number;
  frontHeight: number;
  frontFullBleed?: boolean;
}
export function checkBackCoverText(text: string): string | null;
export function createPaperbackCover(input: CoverPdfInput): Promise<{ blob: Blob; spineText: boolean; warnings: string[] }>;

// Standalone cover renderer using the same embedded EB Garamond as the interior.
// RGB is intentional. No color conversion, profiles, or standard-font fallbacks.
import PDFDocument from './src/pdfkit/index';
import { EBGARAMOND_FONTS } from './src/font/embedded-fonts';

const PT = 72;
const BLEED = 9;
const BACK_FONT = 14;
const BACK_WIDTH = 5 * PT;
const BACK_HEIGHT = 6.5 * PT;
const BACK_OPTIONS = { width: BACK_WIDTH, lineGap: 3, paragraphGap: 7, align: 'left' };
const BG = '#f3efe5';
const INK = '#211d17';
let fontBytes;
function regularFont() {
  if (!fontBytes) {
    const data = EBGARAMOND_FONTS.fonts[0].src.split(',')[1];
    fontBytes = Uint8Array.from(atob(data), (character) => character.charCodeAt(0));
  }
  return fontBytes;
}

function documentWithFont(options = {}) {
  const doc = new PDFDocument({ autoFirstPage: false, compress: true, ...options });
  doc.registerFont('EBGaramond', regularFont());
  doc.font('EBGaramond');
  return doc;
}

function missingCharacter(doc, text) {
  return Array.from(text).find((character) => !/\s/u.test(character) &&
    !doc._font.font.hasGlyphForCodePoint(character.codePointAt(0)));
}

function checkText(doc, text) {
  if (Array.from(text).length > 1500) return 'Keep the back-cover text to 1,500 characters, including spaces.';
  const missing = missingCharacter(doc, text);
  if (missing) return `EB Garamond cannot print “${missing}”. Please replace that character.`;
  doc.fontSize(BACK_FONT);
  if (text.trim() && doc.heightOfString(text.trim(), BACK_OPTIONS) > BACK_HEIGHT) {
    return 'This text needs more space than the back cover allows. Shorten it or remove extra blank lines; the lettering stays at 14 points.';
  }
  return null;
}

export function checkBackCoverText(text) {
  const doc = documentWithFont();
  try { return checkText(doc, text); }
  finally { doc.destroy(); }
}

export async function createPaperbackCover(input) {
  const { title, author, backText, printPages, spine, frontImage, frontWidth, frontHeight } = input;
  if (!Number.isFinite(spine) || spine <= 0 || !Number.isInteger(printPages) || printPages < 24) {
    throw new Error('Invalid paperback dimensions.');
  }
  const doc = documentWithFont({ info: { Title: `${title} — Paperback Cover`, Author: author } });
  const textError = checkText(doc, backText);
  if (textError) { doc.destroy(); throw new Error(textError); }
  const width = (12.25 + spine) * PT;
  const height = 9.25 * PT;
  const chunks = [];
  const completed = new Promise((resolve, reject) => {
    doc.on('data', (chunk) => chunks.push(new Uint8Array(chunk)));
    doc.on('error', reject);
    doc.on('end', () => resolve(new Blob(chunks, { type: 'application/pdf' })));
  });
  const warnings = [];
  let spineText = false;
  try {
    doc.addPage({ size: [width, height], margin: 0 });
    doc.rect(0, 0, width, height).fill(BG);
    doc.fillColor(INK).fontSize(BACK_FONT);
    if (backText.trim()) doc.text(backText.trim(), BLEED + 0.5 * PT, BLEED + 0.65 * PT, BACK_OPTIONS);

    // Keep a 2 x 1.2-inch barcode box clear, 0.25 inch from spine and bottom trim.
    doc.rect(BLEED + (6 - 0.25 - 2) * PT, BLEED + (9 - 0.25 - 1.2) * PT, 2 * PT, 1.2 * PT).fill('#ffffff');

    // A prepared front panel includes its own bleed and any author-chosen border.
    const frontX = BLEED + (6 + spine) * PT;
    doc.save().rect(frontX, 0, 6.125 * PT, height).clip();
    if (input.frontFullBleed) {
      doc.image(frontImage, frontX, 0, { width: 6.125 * PT, height });
    } else {
      doc.image(frontImage, frontX + (6 - frontWidth) * PT / 2,
        BLEED + (9 - frontHeight) * PT / 2, { width: frontWidth * PT, height: frontHeight * PT });
    }
    doc.restore();

    // Read down the spine. Title starts near the top; author ends near the bottom.
    const safeWidth = spine * PT - 2 * 0.0625 * PT;
    const cleanTitle = title.replace(/\s+/gu, ' ').trim();
    const cleanAuthor = author.replace(/\s+/gu, ' ').trim();
    let size = 18;
    while (size >= 7) {
      doc.fontSize(size);
      if (doc.currentLineHeight(true) <= safeWidth &&
          doc.widthOfString(cleanTitle) <= 4.75 * PT &&
          doc.widthOfString(cleanAuthor) <= 2.75 * PT) break;
      size -= 0.5;
    }
    if (printPages >= 80 && size >= 7 && cleanTitle && cleanAuthor &&
        !missingCharacter(doc, cleanTitle + cleanAuthor)) {
      spineText = true;
      const center = BLEED + 6 * PT + spine * PT / 2;
      const lineHeight = doc.currentLineHeight(true);
      const sideways = (text, y) => {
        doc.save().translate(center, y).rotate(90).fillColor(INK);
        doc.text(text, 0, -lineHeight / 2, { lineBreak: false });
        doc.restore();
      };
      sideways(cleanTitle, BLEED + 0.5 * PT);
      sideways(cleanAuthor, BLEED + 8.5 * PT - doc.widthOfString(cleanAuthor));
    } else {
      warnings.push('Spine lettering was left off because it would not fit safely at a readable size.');
    }
    doc.end();
  } catch (error) {
    doc.destroy(error);
  }
  const blob = await completed;
  if (blob.size > 650 * 1000 * 1000) throw new Error('The cover PDF exceeds KDP’s 650 MB limit.');
  if (blob.size > 40 * 1000 * 1000) warnings.push('This cover PDF is larger than KDP’s recommended 40 MB.');
  return { blob, spineText, warnings };
}

import type JSZip from 'jszip';
import { createPaperbackCover } from 'book-pdf/cover';
import { extractEpubCover } from './epub-cover';
import { COVER_BACKGROUND, FRONT_WIDTH, FRONT_HEIGHT, coverDimensions, frontPlacement, frontImageWarnings, paperbackPublishingNote, type FrontFit, type PaperbackCoverOptions } from './paperback-cover';

export interface PreparedFrontImage {
  dataUrl: string;
  sourceWidth: number;
  sourceHeight: number;
  dpi: number;
  fit: FrontFit;
  warnings: string[];
}

// Keep the whole uploaded artwork in the one saved JPEG, so placement can change.
export async function normalizeFrontUpload(file: File): Promise<{ name: string; jpeg: string }> {
  if (!(['image/jpeg', 'image/png'].includes(file.type) || (!file.type && /\.(jpe?g|png)$/i.test(file.name)))) {
    throw new Error('Choose a JPG or PNG image for the front cover.');
  }
  const url = URL.createObjectURL(file);
  const canvas = document.createElement('canvas');
  try {
    const image = new Image(); image.src = url; await image.decode();
    const placement = frontPlacement(image.naturalWidth, image.naturalHeight, 'fill');
    const scale = Math.min(1, 300 / placement.dpi);
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Your browser could not prepare the cover image.');
    context.fillStyle = COVER_BACKGROUND; context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const jpeg = canvas.toDataURL('image/jpeg', 0.95);
    if (!jpeg.startsWith('data:image/jpeg;base64,')) throw new Error('This image is too large for your browser. Choose a smaller JPG or PNG.');
    return { name: file.name.replace(/\.[^.]*$/, '') + '.jpg', jpeg };
  } finally { canvas.width = canvas.height = 1; URL.revokeObjectURL(url); }
}

export async function prepareFrontImage(blob: Blob, fit: FrontFit = 'fill'): Promise<PreparedFrontImage> {
  const url = URL.createObjectURL(blob);
  try {
    const image = new Image();
    image.src = url;
    await image.decode();
    const placement = frontPlacement(image.naturalWidth, image.naturalHeight, fit);
    // Prepare only the front panel. Cap at 300 DPI; do not upscale small images.
    const dpi = Math.min(300, placement.dpi);
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(FRONT_WIDTH * dpi));
    canvas.height = Math.max(1, Math.round(FRONT_HEIGHT * dpi));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Your browser could not prepare the cover image.');
    context.fillStyle = COVER_BACKGROUND;
    context.fillRect(0, 0, canvas.width, canvas.height);
    // Separate scales account for whole-pixel canvas rounding at its outer edges.
    const sx = canvas.width / FRONT_WIDTH, sy = canvas.height / FRONT_HEIGHT;
    context.drawImage(image, placement.x * sx, placement.y * sy, placement.width * sx, placement.height * sy);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
    // Free the pixel buffer promptly when creating large illustrated books.
    canvas.width = canvas.height = 1;
    if (!dataUrl.startsWith('data:image/jpeg;base64,')) throw new Error('Your browser could not prepare this image. Choose another JPG or PNG.');
    return { dataUrl, sourceWidth: image.naturalWidth, sourceHeight: image.naturalHeight,
      dpi: placement.dpi, fit, warnings: frontImageWarnings(image.naturalWidth, image.naturalHeight, fit) };
  } finally { URL.revokeObjectURL(url); }
}

export interface PaperbackCoverResult {
  blob: Blob;
  warnings: string[];
  dimensions: ReturnType<typeof coverDimensions>;
}

export async function generatePaperbackCover(
  zip: JSZip, pageCount: number, options: PaperbackCoverOptions,
  title: string, author: string, cancelled: () => boolean = () => false,
  selectedFront?: PreparedFrontImage,
): Promise<PaperbackCoverResult> {
  const check = () => { if (cancelled()) throw new DOMException('Cancelled', 'AbortError'); };
  check();
  const dimensions = coverDimensions(pageCount, options.paper);
  const front = selectedFront ?? await prepareFrontImage(await extractEpubCover(zip));
  check();
  const result = await createPaperbackCover({
    title, author, backText: options.backText, printPages: dimensions.printPages,
    spine: dimensions.spine, frontImage: front.dataUrl, frontWidth: FRONT_WIDTH, frontHeight: FRONT_HEIGHT, frontFullBleed: true,
  });
  check();
  const warnings = [...front.warnings, ...result.warnings];
  const publishingNote = paperbackPublishingNote(pageCount, options.paper);
  if (publishingNote) warnings.push(publishingNote);
  if (dimensions.pdfPages !== dimensions.printPages) warnings.push(
    `The PDF has ${dimensions.pdfPages} pages. The cover allows for ${dimensions.printPages}, because KDP rounds up to an even page count.`,
  );
  return { blob: result.blob, dimensions, warnings };
}

// @vitest-environment node
import { describe, expect, it } from 'vitest';
import { coverDimensions, frontPlacement, frontImageWarnings, FRONT_WIDTH, FRONT_HEIGHT, characterCount, limitBackText, paperbackPublishingNote, PAPER_CHOICES, type PaperChoice } from './paperback-cover';
import { checkBackCoverText, createPaperbackCover } from 'book-pdf/cover';
import fs from 'node:fs';

describe('6x9 paperback cover', () => {
  it('uses the published KDP dimensions and rounds odd page counts up', () => {
    expect(coverDimensions(300, 'bw-cream')).toMatchObject({ spine: 0.75, width: 13, height: 9.25 });
    expect(coverDimensions(299, 'bw-cream').printPages).toBe(300);
    expect(coverDimensions(300, 'bw-white').spine).toBeCloseTo(0.6756, 6);
    expect(coverDimensions(300, 'standard-color').spine).toBeCloseTo(0.6756, 6);
    expect(coverDimensions(300, 'premium-color').spine).toBeCloseTo(0.7041, 6);
  });
  it('uses the calculator range for every paper and checks before rounding', () => {
    for (const paper of Object.keys(PAPER_CHOICES) as PaperChoice[]) {
      expect(coverDimensions(24, paper).printPages).toBe(24);
      expect(coverDimensions(829, paper).printPages).toBe(830);
      expect(coverDimensions(830, paper).printPages).toBe(830);
      for (const pages of [23, 831, 871]) expect(() => coverDimensions(pages, paper)).toThrow(/24–830/);
    }
    expect(() => coverDimensions(NaN, 'bw-white')).toThrow(/invalid/);
    expect(() => coverDimensions(24.5, 'bw-white')).toThrow(/invalid/);
  });
  it('keeps narrower publishing ranges as notes without blocking calculation', () => {
    expect(paperbackPublishingNote(70, 'standard-color')).toMatch(/72–600/);
    expect(paperbackPublishingNote(777, 'bw-cream')).toMatch(/24–776/);
    expect(paperbackPublishingNote(830, 'bw-white')).toMatch(/24–828/);
    expect(paperbackPublishingNote(830, 'premium-color')).toMatch(/24–828/);
    expect(paperbackPublishingNote(600, 'standard-color')).toBe('');
    expect(paperbackPublishingNote(776, 'bw-cream')).toBe('');
    expect(paperbackPublishingNote(828, 'bw-white')).toBe('');
  });
  it('covers the entire front panel including bleed for every image shape', () => {
    for (const [width, height] of [[2450, 3700], [600, 900], [1000, 1000], [2200, 1100]]) {
      const p = frontPlacement(width!, height!);
      expect(p.x).toBeLessThanOrEqual(0.000001); expect(p.y).toBeLessThanOrEqual(0.000001);
      expect(p.x + p.width).toBeGreaterThanOrEqual(FRONT_WIDTH - 0.000001);
      expect(p.y + p.height).toBeGreaterThanOrEqual(FRONT_HEIGHT - 0.000001);
    }
    expect(frontImageWarnings(1838, 2775, 'fill')).toEqual([]);
    expect(frontImageWarnings(2200, 1100, 'fill').join(' ')).toMatch(/cropped/);
    expect(frontPlacement(600, 900).dpi).toBeLessThan(300);
  });
  it('keeps the entire image only when the author chooses a warned border', () => {
    expect(frontPlacement(1650, 2550, 'border')).toMatchObject({ width: 5.5, height: 8.5, dpi: 300, x: 0.25, y: 0.375 });
    expect(frontPlacement(2200, 1100, 'border')).toMatchObject({ width: 5.5, height: 2.75, cropSides: false, cropTopBottom: false });
    expect(frontImageWarnings(1650, 2550, 'border')[0]).toMatch(/cream border/);
  });
  it('counts spaces and Unicode characters without splitting surrogate pairs', () => {
    expect(characterCount('A 😀 B')).toBe(5);
    expect(characterCount(limitBackText('😀'.repeat(1600)))).toBe(1500);
  });
  it('checks actual 14-point text fit as well as character count', () => {
    expect(checkBackCoverText('A quiet story about the people who stay.')).toBeNull();
    expect(checkBackCoverText('x'.repeat(1501))).toMatch(/1,500/);
    expect(checkBackCoverText('A\n'.repeat(100))).toMatch(/more space/);
    expect(checkBackCoverText('A story 😀')).toMatch(/cannot print/);
    expect(checkBackCoverText('')).toBeNull();
  });
  it('renders a single cover with a thick spine and omits lettering on a thin one', async () => {
    const image = fs.readFileSync('public/images/sand-texture.jpg').toString('base64');
    const input = { title: 'The Quiet Valley', author: 'Clee Smith', backText: 'The road follows the river until it runs out of room.',
      printPages: 300, spine: 0.75, frontImage: `data:image/jpeg;base64,${image}`, frontWidth: 5.5, frontHeight: 8.25 };
    const thick = await createPaperbackCover(input);
    expect(thick.spineText).toBe(true);
    expect(thick.blob.size).toBeGreaterThan(1000);
    const thin = await createPaperbackCover({ ...input, printPages: 24, spine: 0.054048 });
    expect(thin.spineText).toBe(false);
    expect(thin.warnings[0]).toMatch(/left off/);
    const full = await createPaperbackCover({ ...input, frontFullBleed: true });
    expect(full.blob.size).toBeGreaterThan(1000);
    if (process.env.COVER_TEST_OUTPUT) fs.writeFileSync(process.env.COVER_TEST_OUTPUT, new Uint8Array(await full.blob.arrayBuffer()));
  });
});

// KDP paperback rules, deliberately limited to the existing 6 x 9 export.
export const BACK_COVER_LIMIT = 1500;
// Match the cover calculator's input range. Publishing ranges below are advisory.
export const COVER_PAGE_MIN = 24;
export const COVER_PAGE_MAX = 830;
export const PAPER_CHOICES = {
  'bw-white': { label: 'Black-and-white on white paper', factor: 0.002252, min: 24, max: 828 },
  'bw-cream': { label: 'Black-and-white on cream paper', factor: 0.0025, min: 24, max: 776 },
  'standard-color': { label: 'Standard color on white paper', factor: 0.002252, min: 72, max: 600 },
  'premium-color': { label: 'Premium color on white paper', factor: 0.002347, min: 24, max: 828 },
} as const;
export type PaperChoice = keyof typeof PAPER_CHOICES;
export interface PaperbackCoverOptions { paper: PaperChoice; backText: string }

export function coverDimensions(pdfPages: number, paper: PaperChoice) {
  const choice = PAPER_CHOICES[paper];
  if (!choice || !Number.isSafeInteger(pdfPages) || pdfPages < 1) {
    throw new Error('The finished PDF has an invalid page count or paper choice.');
  }
  if (pdfPages < COVER_PAGE_MIN || pdfPages > COVER_PAGE_MAX) {
    throw new Error(`Page count must be between ${COVER_PAGE_MIN}–${COVER_PAGE_MAX}. This PDF has ${pdfPages} pages.`);
  }
  const printPages = Math.ceil(pdfPages / 2) * 2;
  const spine = printPages * choice.factor;
  return { pdfPages, printPages, spine, width: 12.25 + spine, height: 9.25 };
}

export function paperbackPublishingNote(pdfPages: number, paper: PaperChoice) {
  const { printPages } = coverDimensions(pdfPages, paper);
  const choice = PAPER_CHOICES[paper];
  if (printPages >= choice.min && printPages <= choice.max) return '';
  return `KDP lists ${choice.min}–${choice.max} pages for ${choice.label.toLowerCase()} at 6 × 9 inches. You can calculate this cover, but this page count is outside that publishing range.`;
}

export function characterCount(text: string) { return Array.from(text).length; }
export function limitBackText(text: string) { return Array.from(text).slice(0, BACK_COVER_LIMIT).join(''); }

// Front panel: 6 x 9 trim, plus bleed at top, bottom, and outer edge.
export const FRONT_WIDTH = 6.125;
export const FRONT_HEIGHT = 9.25;
export const COVER_BACKGROUND = '#f3efe5';
export type FrontFit = 'fill' | 'border';

export function frontPlacement(width: number, height: number, fit: FrontFit = 'fill') {
  if (![width, height].every(value => Number.isFinite(value) && value > 0)) throw new Error('The cover image has no usable dimensions.');
  const scale = fit === 'border' ? Math.min(5.5 / width, 8.5 / height) : Math.max(FRONT_WIDTH / width, FRONT_HEIGHT / height);
  const printWidth = width * scale;
  const printHeight = height * scale;
  const x = ((fit === 'border' ? 6 : FRONT_WIDTH) - printWidth) / 2;
  const y = fit === 'border' ? 0.125 + (9 - printHeight) / 2 : (FRONT_HEIGHT - printHeight) / 2;
  return { width: printWidth, height: printHeight, x, y, dpi: 1 / scale,
    cropSides: fit === 'fill' && (printWidth - FRONT_WIDTH) / scale > 1,
    cropTopBottom: fit === 'fill' && (printHeight - FRONT_HEIGHT) / scale > 1 };
}

export function frontImageWarnings(width: number, height: number, fit: FrontFit) {
  const placement = frontPlacement(width, height, fit);
  const warnings: string[] = [];
  if (fit === 'border') warnings.push('This option adds a cream border around the front image. It will be visible in print and may look uneven after trimming. Choose Fill front cover or a different image if you do not want it.');
  if (placement.cropSides || placement.cropTopBottom) warnings.push(`To fill the front cover without an added border, the ${placement.cropSides ? 'sides' : 'top and bottom'} of this image will be cropped. Check the preview, especially any lettering near the edges.`);
  if (placement.dpi < 299.9) warnings.push(`This image is ${width} × ${height} pixels, about ${Math.round(placement.dpi)} DPI at this size, and may look blurry in print. For the same image shape at 300 DPI, use at least ${Math.ceil(width * 300 / placement.dpi)} × ${Math.ceil(height * 300 / placement.dpi)} pixels. You can still use this image.`);
  return warnings;
}

import type { AppService } from '@/types/system';
import type { Book } from '@/types/book';
import { PAPER_CHOICES, type FrontFit, type PaperChoice } from '@/lib/paperback-cover';
import { getPaperbackFrontFilename, getPaperbackSettingsFilename } from '@/utils/book';

export interface SavedPaperbackSettings {
  version: 1;
  pages: string;
  paper: PaperChoice;
  backText: string;
  frontFit: FrontFit;
}

// Small settings records are separate from the one saved JPEG. Serialize explicit
// saves so a reopen cannot read an older save that is still finishing.
const settingsWrites = new Map<string, Promise<void>>();

export async function loadPaperbackSettings(service: AppService, book: Pick<Book, 'hash'>): Promise<SavedPaperbackSettings | null> {
  const filename = getPaperbackSettingsFilename(book);
  await settingsWrites.get(filename)?.catch(() => {});
  let file: File;
  try { file = await service.openFile(filename, 'Books'); }
  catch (error) {
    if (error instanceof Error && error.message.startsWith('File not found:')) return null;
    throw error;
  }
  const record = JSON.parse(await file.text()) as SavedPaperbackSettings;
  if (record.version !== 1 || typeof record.pages !== 'string' ||
      !Object.prototype.hasOwnProperty.call(PAPER_CHOICES, record.paper) ||
      typeof record.backText !== 'string' || !['fill', 'border'].includes(record.frontFit)) {
    throw new Error('The saved paperback details could not be read.');
  }
  return record;
}

export function savePaperbackSettings(service: AppService, book: Pick<Book, 'hash'>, settings: SavedPaperbackSettings): Promise<void> {
  const filename = getPaperbackSettingsFilename(book);
  const content = JSON.stringify(settings);
  const write = (settingsWrites.get(filename) ?? Promise.resolve()).catch(() => {}).then(async () => {
    await service.writeFile(filename, 'Books', content);
  });
  settingsWrites.set(filename, write);
  void write.finally(() => { if (settingsWrites.get(filename) === write) settingsWrites.delete(filename); }).catch(() => {});
  return write;
}

export interface SavedPaperbackFront {
  version: 1;
  name: string;
  jpeg: string;
  fit: FrontFit;
}

// One atomic file record per ebook. The normal Export All Data includes it.
export async function loadPaperbackFront(service: AppService, book: Pick<Book, 'hash'>): Promise<SavedPaperbackFront | null> {
  let file: File;
  try { file = await service.openFile(getPaperbackFrontFilename(book), 'Books'); }
  catch (error) {
    if (error instanceof Error && error.message.startsWith('File not found:')) return null;
    throw error;
  }
  const record = JSON.parse(await file.text()) as SavedPaperbackFront;
  if (record.version !== 1 || typeof record.name !== 'string' || typeof record.jpeg !== 'string' ||
      !record.jpeg.startsWith('data:image/jpeg;base64,') || !['fill', 'border'].includes(record.fit)) {
    throw new Error('The saved paperback image could not be read. Choose another JPG or PNG.');
  }
  return record;
}

export function paperbackFrontFile(record: SavedPaperbackFront): File {
  const bytes = Uint8Array.from(atob(record.jpeg.slice(record.jpeg.indexOf(',') + 1)), character => character.charCodeAt(0));
  return new File([bytes], record.name, { type: 'image/jpeg' });
}

export async function savePaperbackFront(service: AppService, book: Pick<Book, 'hash'>, record: SavedPaperbackFront) {
  await service.writeFile(getPaperbackFrontFilename(book), 'Books', JSON.stringify(record));
}

export async function removePaperbackFront(service: AppService, book: Pick<Book, 'hash'>) {
  await service.deleteFile(getPaperbackFrontFilename(book), 'Books');
}

import React from 'react';
